package main

import (
	"crypto/subtle"
	"fmt"
)

func constantTimeCompare(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	return subtle.ConstantTimeCompare(a, b) == 1
}

func main() {
	password1 := []byte("password123")
	password2 := []byte("password123")
	fmt.Println(constantTimeCompare(password1, password2)) // Output: true
